function priceRange(text:string){const amount="(?:inr\\s*)?(\\d+(?:\\.\\d+)?)";const between=text.match(new RegExp(`${amount}\\s*(?:to|and|se|से|থেকে|થી|ਤੋਂ|முதல்|నుండి|ರಿಂದ|മുതൽ|سے)\\s*${amount}`));if(between)return{minPrice:Number(between[1]),maxPrice:Number(between[2])};const suffix=text.match(/(\d+(?:\.\d+)?)\s*inr\s*(?:or less|ke andar|अंदर|से कम|નીચે|கீழ்|లోపు|ಕಡಿಮೆ|താഴെ|سے کم)/);if(suffix)return{maxPrice:Number(suffix[1])};const under=text.match(new RegExp(`(?:under|below|less than|within|andar|ke andar|अंदर|से कम|નીચે|கீழ்|లోపు|ಕಡಿಮೆ|താഴെ|سے کم)\\s*${amount}|${amount}\\s*(?:or less|ke andar|अंदर|से कम|નીચે|கீழ்|లోపు|ಕಡಿಮೆ|താഴെ|سے کم)`));return under?{maxPrice:Number(under[1]??under[2])}:{}}
